import {useState} from "react";import {hydrateRoot,type Root} from "react-dom/client";import {renderToString} from "react-dom/server";import {act,fireEvent,within} from "@testing-library/react";import {afterEach,expect,test,vi} from "vitest";import {App} from "./App";import {initial,parseBoot,readBoot,relativeLabel} from "./bootModel";import {RelativeTime,OnlineLabel,ThemeBadge,ClientOnly} from "./browserValues";import {rootMarkup,renderPage} from "./render.server";import {mountHydrated,type Recovery} from "./hydrate";const roots=new Set<Root>();afterEach(async()=>{for(const root of roots)await act(async()=>root.unmount());roots.clear();localStorage.clear();});function container(html:string){const node=document.createElement("div");node.innerHTML=html;document.body.append(node);return node;}async function hydrateCase(node:Element,element:React.ReactNode){const errors:unknown[]=[];await act(async()=>{roots.add(hydrateRoot(node,element,{onRecoverableError:error=>errors.push(error)}));});return errors;}
test("zgodne dane zachowują istniejący DOM i podłączają interakcję",async()=>{const node=container(rootMarkup(initial)),heading=node.querySelector("h1"),input=node.querySelector("input"),errors:Recovery[]=[];await act(async()=>{roots.add(mountHydrated(node,initial,error=>errors.push(error)));});expect(errors).toEqual([]);expect(node.querySelector("h1")).toBe(heading);expect(node.querySelector("input")).toBe(input);expect(node.querySelector("label")?.htmlFor).toBe(input?.id);await act(async()=>fireEvent.click(within(node).getByRole("button")));expect(within(node).getByRole("button")).toHaveTextContent("Licznik: 1");});
test("różnica tekstu zgłasza recovery bez raportowania prywatnego diffu",async()=>{const node=container(rootMarkup(initial)),heading=node.querySelector("h1"),errors:Recovery[]=[];await act(async()=>{roots.add(mountHydrated(node,{...initial,article:{...initial.article,title:"TAJNY-TYTUŁ"}},error=>errors.push(error)));});expect(errors.length).toBeGreaterThan(0);expect(node.querySelector("h1")).not.toBe(heading);expect(JSON.stringify(errors)).not.toContain("TAJNY");expect(Object.keys(errors[0])).toEqual(["kind","name"]);});
test("różny snapshot licznika jest wykrywany jako mismatch",async()=>{const node=container(rootMarkup(initial)),errors:Recovery[]=[];await act(async()=>{roots.add(mountHydrated(node,{...initial,counter:9},error=>errors.push(error)));});expect(errors.length).toBeGreaterThan(0);expect(within(node).getByRole("button")).toHaveTextContent("Licznik: 9");});
test("czas względny zaczyna od UTC i aktualizuje się dopiero po hydratacji",async()=>{const iso="2026-10-01T10:00:00.000Z",clock=()=>Date.parse("2026-10-01T10:20:00Z"),element=<RelativeTime iso={iso} clock={clock}/>;const html=renderToString(element);expect(html).toContain("2026-10-01</time>");const node=container(html),time=node.querySelector("time"),errors=await hydrateCase(node,element);expect(errors).toEqual([]);expect(node.querySelector("time")).toBe(time);expect(time).toHaveTextContent("20 min temu");});
test("online ma zgodny snapshot serwerowy i potem odczyt klienta",async()=>{let online=false;vi.spyOn(navigator,"onLine","get").mockImplementation(()=>online);const element=<OnlineLabel/>,html=renderToString(element);expect(html).toContain("online");const node=container(html),errors=await hydrateCase(node,element);expect(errors).toEqual([]);expect(node).toHaveTextContent("offline");online=true;await act(async()=>window.dispatchEvent(new Event("online")));expect(node).toHaveTextContent("online");});
test("motyw z localStorage nie zmienia pierwszego renderu",async()=>{localStorage.setItem("theme","dark");const element=<ThemeBadge/>,html=renderToString(element);expect(html).toContain("light");const node=container(html),errors=await hydrateCase(node,element);expect(errors).toEqual([]);expect(node).toHaveTextContent("dark");});
test("ClientOnly nie wykonuje przeglądarkowego dziecka podczas SSR",async()=>{let calls=0;function Browser(){calls++;return <p>Przeglądarka</p>;}const element=<ClientOnly fallback={<p>Placeholder</p>}><Browser/></ClientOnly>,html=renderToString(element);expect(calls).toBe(0);expect(html).toContain("Placeholder");const node=container(html),errors=await hydrateCase(node,element);expect(errors).toEqual([]);expect(node).toHaveTextContent("Przeglądarka");});
test("dwa root mają oddzielne prefix useId i poprawne etykiety",async()=>{const a={...initial,prefix:"first-"},b={...initial,prefix:"second-"},one=container(rootMarkup(a)),two=container(rootMarkup(b)),errors:Recovery[]=[];await act(async()=>{roots.add(mountHydrated(one,a,error=>errors.push(error)));roots.add(mountHydrated(two,b,error=>errors.push(error)));});expect(errors).toEqual([]);expect(one.querySelector("input")?.id).not.toBe(two.querySelector("input")?.id);expect(one.querySelector("label")?.htmlFor).toBe(one.querySelector("input")?.id);expect(two.querySelector("label")?.htmlFor).toBe(two.querySelector("input")?.id);});
test("błędne HTML naprawione przez parser prowadzi do mismatch",async()=>{vi.spyOn(console,"error").mockImplementation(()=>{});const element=<p><div>Blok w akapicie</div></p>,node=container(renderToString(element)),errors=await hydrateCase(node,element);expect(errors.length).toBeGreaterThan(0);});
test("dokument zachowuje JSON danych i nie tworzy skryptu z treści",()=>{const boot={...initial,article:{...initial.article,body:'</script><script>alert(1)</script>'}},html=renderPage(boot,"/assets/main.js"),parsed=new DOMParser().parseFromString(html,"text/html");expect(readBoot(parsed).article.body).toBe(boot.article.body);expect(parsed.querySelectorAll('script:not([type="application/json"])')).toHaveLength(1);expect(parsed.querySelector('script[type="module"]')?.getAttribute("src")).toBe("/assets/main.js");expect(parsed.querySelector("article script")).toBeNull();});
test("walidacja odrzuca obcy kształt boot i prywatne dane",()=>{for(const value of [{...initial,counter:-1},{...initial,counter:.5},{...initial,prefix:"<script>"},{...initial,article:{...initial.article,audience:"private"}}])expect(()=>parseBoot(value)).toThrow();expect(()=>renderPage(initial,"https://evil.example/x.js")).toThrow();expect(relativeLabel("2026-10-01T10:00:00Z",Date.parse("2026-10-01T09:59:00Z"))).toBe("0 min temu");});
test("cleanup hydratowanego root usuwa listenery online i offline",async()=>{const remove=vi.spyOn(window,"removeEventListener"),node=container(renderToString(<OnlineLabel/>));let root!:Root;await act(async()=>{root=hydrateRoot(node,<OnlineLabel/>);});await act(async()=>root.unmount());expect(remove).toHaveBeenCalledWith("online",expect.any(Function));expect(remove).toHaveBeenCalledWith("offline",expect.any(Function));});

